package mx.uv.dsw.telemetry; import java.time.Instant; import javax.persistence.*; import javax.validation.constraints.*; @Entity public class Telemetry {@Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @NotBlank @Size(max=64) private String deviceId; @NotNull @DecimalMin("-100.0") @DecimalMax("200.0") @Column(name="measurement_value") private Double value; private Instant capturedAt=Instant.now(); public Long getId(){return id;} public String getDeviceId(){return deviceId;} public void setDeviceId(String v){deviceId=v;} public Double getValue(){return value;} public void setValue(Double v){value=v;} public Instant getCapturedAt(){return capturedAt;} public void setCapturedAt(Instant v){capturedAt=v;}}
